{"policy":"permit (
    principal is Person,
    action == Action::"openEscrowFile",
    resource is EscrowFile
) when {
    principal.isEscrowOfficer
};

permit (
    principal is Person,
    action == Action::"approveClearToClose",
    resource is EscrowFile
) when {
    principal.isTitleOfficer || principal.isEscrowManager
};

permit (
    principal is Person,
    action == Action::"viewAuditLog",
    resource is AuditLog
) when {
    principal.isAuditor
};

forbid (
    principal is Person,
    action == Action::"approveClearToClose",
    resource is EscrowFile
) when {
    resource.openedBy == principal
};

forbid (
    principal is Person,
    action == Action::"approveClearToClose",
    resource is EscrowFile
) when {
    !resource.titleCleared
};

forbid (
    principal is Person,
    action,
    resource
) when {
    principal.isAuditor && action != Action::"viewAuditLog"
};"}
